window.COURSE={"title":"My Clinic — Welcome On Board: My Clinic & HR Essentials","short_title":"Welcome On Board: My Clinic & HR Essentials","prefix":"hr","module":"03","colour":"#652D8C","colour_ink":null,"duration":45,"tracking":{"completion_rule":"viewed_all_and_passed","passing_score":70},"objectives":[{"id":"hr-o1","description":"Link My Clinic's values and 7C strategy to everyday actions in your role."},{"id":"hr-o2","description":"Apply the code of ethics and patients' rights and responsibilities to workplace situations."},{"id":"hr-o3","description":"Decide whether a leave request is eligible and how many days apply."},{"id":"hr-o4","description":"Calculate a GOSI deduction and an overtime payment."},{"id":"hr-o5","description":"Choose the correct system (Oracle, intranet, Qiwa, Mumaris) and submit a leave request in Oracle."},{"id":"hr-o6","description":"Apply ID card, dress-code and resignation rules."}],"variables":[{"name":"role","type":"text","default":"all"},{"name":"role_label","type":"text","default":"team member"},{"name":"xp","type":"number","default":0},{"name":"meter","type":"number","default":3},{"name":"hint","type":"number","default":0}],"points_var":"xp","levels":[{"name":"New Joiner","min_points":0},{"name":"Team Member","min_points":53},{"name":"Insider","min_points":107},{"name":"Culture Ambassador","min_points":151}],"lives_var":"meter","max_lives":5,"meter_label":"Team trust","titles":{"A · Welcome":"Welcome","B · Our values & strategy":"Mission 1 · Our values & strategy","C · Our clinic":"Mission 2 · Our clinic","D · Ethics & patients' rights":"Mission 3 · Ethics & patients' rights","E · Your leave":"Mission 4 · Your leave","F · Pay & social insurance":"Mission 5 · Pay & social insurance","G · Systems & licences":"Mission 6 · Systems & licences","H · ID, benefits & dress code":"Mission 7 · ID, benefits & dress code","I · Contracts & leaving":"Mission 8 · Contracts & leaving","Z · Close":"Close"},"assets":{"brand-background-title-navy":"assets/brand-background-title-navy.png","char-omar-welcome":"assets/char-omar-welcome.png","char-noor-welcome":"assets/char-noor-welcome.png","char-omar-explaining":"assets/char-omar-explaining.png","brand-value-tile-collaborative-burgundy":"assets/brand-value-tile-collaborative-burgundy.png","brand-value-tile-responsible-magenta":"assets/brand-value-tile-responsible-magenta.png","brand-value-tile-ambitious-teal":"assets/brand-value-tile-ambitious-teal.png","brand-value-tile-caring-purple":"assets/brand-value-tile-caring-purple.png","hr-img-7c-closer":"assets/hr-img-7c-closer.svg","hr-img-7c-cure":"assets/hr-img-7c-cure.svg","hr-img-7c-capabilities":"assets/hr-img-7c-capabilities.svg","hr-img-7c-culture":"assets/hr-img-7c-culture.svg","hr-img-7c-clinicians":"assets/hr-img-7c-clinicians.svg","hr-img-7c-care":"assets/hr-img-7c-care.svg","hr-img-7c-cost":"assets/hr-img-7c-cost.svg","hr-img-map":"assets/hr-img-map.svg","hr-img-award-star":"assets/hr-img-award-star.svg","hr-img-award-trophy":"assets/hr-img-award-trophy.svg","hr-img-ethics-icons":"assets/hr-img-ethics-icons.svg","hr-img-ethics-meeting":"assets/hr-img-ethics-meeting.jpg","hr-img-ethics-corridor":"assets/hr-img-ethics-corridor.jpg","hr-img-ethics-desk":"assets/hr-img-ethics-desk.jpg","char-noor-avatar-neutral":"assets/char-noor-avatar-neutral.png","hr-img-help-icons":"assets/hr-img-help-icons.svg","hr-img-leavedesk":"assets/hr-img-leavedesk.jpg","hr-img-gosi-bar":"assets/hr-img-gosi-bar.svg","hr-img-oracle-1":"assets/hr-img-oracle-1.svg","hr-img-oracle-2":"assets/hr-img-oracle-2.svg","hr-img-oracle-3":"assets/hr-img-oracle-3.svg","hr-img-oracle-4":"assets/hr-img-oracle-4.svg","hr-img-oracle-5":"assets/hr-img-oracle-5.svg","hr-img-idcard":"assets/hr-img-idcard.jpg","hr-img-benefits-wheel":"assets/hr-img-benefits-wheel.svg","hr-img-exit-icons":"assets/hr-img-exit-icons.svg","hr-img-challenge":"assets/hr-img-challenge.jpg","char-noor-explaining":"assets/char-noor-explaining.png","brand-logo-horizontal-navy":"assets/brand-logo-horizontal-navy.png","font-montserrat-400":"assets/montserrat-latin-400-normal.woff2","font-montserrat-600":"assets/montserrat-latin-600-normal.woff2","font-montserrat-700":"assets/montserrat-latin-700-normal.woff2"},"logo":"assets/brand-logo-horizontal-navy.png","petal":"assets/mark-white.png","screens":[{"type":"title_slide","id":"hr-000","title":"Welcome On Board","subtitle":"My Clinic & HR essentials · about 45 minutes","section":"A · Welcome","objective_ids":[],"points":0,"body_html":"<div class=\"mc-guides\"><div class=\"mc-guide omar\">{{asset:char-omar-welcome}}<span>Dr. Omar</span></div><div class=\"mc-guide noor\">{{asset:char-noor-welcome}}<span>Noor</span></div></div>"},{"type":"content_slide","id":"hr-001","title":"Why we exist","section":"A · Welcome","objective_ids":[],"points":0,"layout":"text_media","media_asset_id":"char-omar-explaining","media_alt":"Dr. Omar, a family physician, presenting the clinic's purpose, mission and goal.","body_html":"<p><strong>Purpose</strong> — helping people live longer, healthier, happier lives</p><p><strong>Mission</strong> — the world's most customer-centric healthcare company</p><p><strong>Goal</strong> — outstanding patient experience + excellent clinical outcomes</p>"},{"type":"poll","id":"hr-002","title":"One million riyals","section":"A · Welcome","objective_ids":[],"points":0,"prompt_html":"<p>If you had one million Saudi riyals, where would you spend it?</p>","options":[{"id":"a","text_html":"Family"},{"id":"b","text_html":"Travel"},{"id":"c","text_html":"Learning"},{"id":"d","text_html":"Giving back"},{"id":"e","text_html":"Other"}],"multi":false,"allow_text":true,"reflection_html":"<p>Whatever you chose says something you care about. At My Clinic, we start from what people care about — including yours.</p>","on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"branching","id":"hr-003","title":"Make it yours","prompt_html":"<p><strong>Which best describes your role?</strong></p><p>We'll add tips for your work. Every scored activity is the same for everyone.</p>","choices":[{"id":"clinical","text_html":"<strong>Medical team</strong><br><small>Physicians, dentists, nurses, allied health</small>","goto_screen_id":"hr-00m","set_vars":[{"var":"role","op":"set","value":"clinical"},{"var":"role_label","op":"set","value":"clinician"}]},{"id":"front","text_html":"<strong>Front office</strong><br><small>Reception, call centre, patient experience, My Care</small>","goto_screen_id":"hr-00m","set_vars":[{"var":"role","op":"set","value":"front"},{"var":"role_label","op":"set","value":"front-office colleague"}]},{"id":"support","text_html":"<strong>Back office</strong><br><small>Admin, HR, finance, RCM, IT, facilities</small>","goto_screen_id":"hr-00m","set_vars":[{"var":"role","op":"set","value":"support"},{"var":"role_label","op":"set","value":"back-office colleague"}]},{"id":"all","text_html":"<strong>Show me every role's tips</strong>","goto_screen_id":"hr-00m","set_vars":[{"var":"role","op":"set","value":"all"},{"var":"role_label","op":"set","value":"team member"}]}],"default_goto":"hr-00m","points":0,"objective_ids":[],"section":"A · Welcome"},{"type":"content_slide","id":"hr-00m","title":"First 90 days challenge","layout":"text_media","body_html":"<h3>Can you find your way through your first 90 days?</h3><p class=\"mc-missions\"><strong>8 missions:</strong> <strong>1</strong> Our values & strategy · <strong>2</strong> Our clinic · <strong>3</strong> Ethics & patients' rights · <strong>4</strong> Your leave · <strong>5</strong> Pay & social insurance · <strong>6</strong> Systems & licences · <strong>7</strong> ID, benefits & dress code · <strong>8</strong> Contracts & leaving</p><p class=\"mc-xp-rules\"><strong>Earn XP:</strong> +10 for each activity you get right · +5 for each quick check · +2 for each screen you explore. <strong>Ranks:</strong> New Joiner → Team Member → Insider → Culture Ambassador.</p><p><strong>Team trust</strong> (the dots at the top) goes up with each good decision and down with each risky one. Ask Noor or Dr. Omar for a hint before a big decision.</p><p class=\"mc-note\">XP is just for you: it never counts towards your pass mark.</p>","points":0,"objective_ids":[],"media_asset_id":"hr-img-challenge","media_alt":"Illustration for the first 90 days challenge.","section":"A · Welcome"},{"type":"tabs","id":"hr-010","title":"Our four values","section":"B · Our values & strategy","objective_ids":[],"points":0,"prompt_html":"<p>Values are behaviours. Open each one and look for something you already do.</p>","tabs":[{"label":"Collaborative","body_html":"<p><strong>Unites diverse</strong></p><p>Act together · Treat everyone with respect · Be transparent · Embrace diverse perspectives · Deliver outstanding results</p>","image_asset_id":"brand-value-tile-collaborative-burgundy","image_alt":"Decorative icon."},{"label":"Responsible","body_html":"<p><strong>Creating a culture of accountability</strong></p><p>Own our decisions and actions · Make things happen · Demonstrate high professional standards · Hold yourself and each other accountable</p>","image_asset_id":"brand-value-tile-responsible-magenta","image_alt":"Decorative icon."},{"label":"Ambitious","body_html":"<p><strong>Set new standards</strong></p><p>Go above and beyond · Make new possibilities happen · Challenge the status quo · Become industry shapers · Deliver outstanding results</p>","image_asset_id":"brand-value-tile-ambitious-teal","image_alt":"Decorative icon."},{"label":"Caring","body_html":"<p><strong>Putting empathy first</strong></p><p>Act with empathy · Everyone matters · Love our customers · Deliver with quality</p>","image_asset_id":"brand-value-tile-caring-purple","image_alt":"Decorative icon."}],"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"matching","id":"hr-011","title":"Values in action","section":"B · Our values & strategy","objective_ids":["hr-o1"],"points":10,"prompt_html":"<p>Six things people did this week. Match each one to the value behind it.</p>","pairs":[{"id":"p1","left_html":"You admit a scheduling mistake to your manager and fix it.","right_html":"Responsible"},{"id":"p2","left_html":"You ask a colleague in another department for their view before you decide.","right_html":"Collaborative"},{"id":"p3","left_html":"You stay with an anxious patient until the nurse arrives.","right_html":"Caring"},{"id":"p4","left_html":"You suggest a faster way to book follow-up appointments.","right_html":"Ambitious"},{"id":"p5","left_html":"You share the reason for a delay with the team instead of staying quiet.","right_html":"Collaborative"},{"id":"p6","left_html":"You check your own work against the professional standard before you sign it off.","right_html":"Responsible"}],"feedback":{"correct_html":"<p>Right. Notice that Responsible and Collaborative each appear twice: the values overlap in real work, and one action can show more than one.</p>","incorrect_html":"<p>Not all six. Read each action again and ask what the person was actually choosing to do — own it, involve others, reach further, or care for someone.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"accordion","id":"hr-012","title":"The 7C strategy","section":"B · Our values & strategy","objective_ids":[],"points":0,"prompt_html":"<p>Seven pillars. Open the ones your role touches — you're not expected to memorise all seven.</p>","items":[{"title":"Closer","body_html":"<p><strong>Convenient &amp; easy access</strong></p><p>Convenient physical access · Community clinics &amp; HHC · Digital access &amp; services · Call centre &amp; telemedicine</p>","image_asset_id":"hr-img-7c-closer","image_alt":"Decorative icon."},{"title":"Cure","body_html":"<p><strong>Tackle the biggest healthcare challenge</strong></p><p>The best Saudi doctors · Focus on clinical outcomes · Centres of excellence · Prevention &amp; wellbeing</p>","image_asset_id":"hr-img-7c-cure","image_alt":"Decorative icon."},{"title":"Capabilities","body_html":"<p><strong>A repeatable business model</strong></p><p>Repeatable operations &amp; expansion · Robust governance &amp; compliance · Peopleware, software, hardware · Competitive cost to serve</p>","image_asset_id":"hr-img-7c-capabilities","image_alt":"Decorative icon."},{"title":"Culture","body_html":"<p><strong>The way we do things around here</strong></p><p>Mission, values &amp; beliefs · Servant leadership · A culture of excellence</p>","image_asset_id":"hr-img-7c-culture","image_alt":"Decorative icon."},{"title":"Clinicians","body_html":"<p><strong>An attractive doctor value proposition</strong></p><p>Caring environment · Competitive benefits · Growth &amp; development</p>","image_asset_id":"hr-img-7c-clinicians","image_alt":"Decorative icon."},{"title":"Care","body_html":"<p><strong>A legendary service &amp; care</strong></p><p>Seamless experience · Empathy &amp; compassion · Loyalty through My Care · Service &amp; advocacy mindset</p>","image_asset_id":"hr-img-7c-care","image_alt":"Decorative icon."},{"title":"Cost","body_html":"<p><strong>Competitive cost to serve</strong></p><p>Revenue-cycle management · Operational efficiency · Overhead management</p>","image_asset_id":"hr-img-7c-cost","image_alt":"Decorative icon."}],"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"mcq","id":"hr-013","title":"Which pillar?","section":"B · Our values & strategy","objective_ids":["hr-o1"],"points":5,"prompt_html":"<p>My Care follow-up calls that build patient loyalty support which pillar?</p>","options":[{"id":"a","text_html":"Care","correct":true,"feedback_html":"<p>Care. My Care follow-up calls are named in the Care pillar under “build loyalty through My Care”. Loyalty is a service and relationship outcome, not an access outcome.</p>"},{"id":"b","text_html":"Closer","feedback_html":"<p>Closer covers <em>access</em>: physical, community and home health care, digital services, and the call centre and telemedicine. A phone call is access; a follow-up call that builds loyalty is Care.</p>"},{"id":"c","text_html":"Culture","feedback_html":"<p>Culture is mission, values and servant leadership. It shapes how we behave, not this service.</p>"},{"id":"d","text_html":"Cost","feedback_html":"<p>Cost is about cost to serve: revenue cycle, efficiency and overhead. Loyalty work sits on the service side.</p>"}],"multi_select":false,"feedback":{"correct_html":"<p>Care. My Care follow-up calls are named in the Care pillar under “build loyalty through My Care”. Loyalty is a service and relationship outcome, not an access outcome.</p>","incorrect_html":"<p>Not quite. Closer is about <em>access</em> — physical, community, digital and telemedicine. Culture is mission, values and leadership. Cost is efficiency. The pillar that names My Care and loyalty is Care.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"flashcards","title":"Who we serve","prompt_html":"<p>Flip each card: who we serve, and how you help them.</p>","cards":[{"front_html":"<strong>Patients &amp; families</strong>","back_html":"<p>Sick or healthy, they come first — every role touches their experience.</p>"},{"front_html":"<strong>Community</strong>","back_html":"<p>Prevention, awareness and the wider Jeddah and Riyadh communities we serve.</p>"},{"front_html":"<strong>Corporates &amp; insurers</strong>","back_html":"<p>Corporate wellness clients and insurance partners rely on accurate, timely work.</p>"}],"id":"hr-014","section":"B · Our values & strategy","points":0,"objective_ids":[],"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"timeline","id":"hr-020","title":"Our story so far","section":"C · Our clinic","objective_ids":[],"points":0,"prompt_html":"<p>From one clinic in Jeddah to a network across the west and Riyadh.</p>","events":[{"date":"2017","title":"MCJ1 opens","body_html":"<p>Our first full-service outpatient clinic, in North Jeddah.</p>"},{"date":"2018","title":"New products","body_html":"<p>New products launched, widening what one clinic could offer.</p>"},{"date":"2019","title":"Corporate check-ups","body_html":"<p>The employment check-up unit starts — our first corporate service line.</p>"},{"date":"2021","title":"MCJ2 opens","body_html":"<p>Our second full-service outpatient clinic, in East Jeddah.</p>"},{"date":"2022","title":"Dental centre","body_html":"<p>My Clinic Dental (D1) opens in Jeddah.</p>"},{"date":"2023","title":"Petro-Rabigh","body_html":"<p>PRC opens — our first clinic inside a corporate community.</p>"},{"date":"2024","title":"Riyadh","body_html":"<p>R1 opens: a flagship clinic in Riyadh to establish the brand.</p>"},{"date":"2025","title":"J3 opens","body_html":"<p>Our first community clinic in Jeddah. <em>Name pending decision B5 / D3.</em></p>"},{"date":"2026","title":"J4 opens","body_html":"<p>Our second community clinic in Jeddah. <em>Name pending decision B5 / D3.</em></p>"}],"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"hotspot","id":"hr-021","title":"Where we are","section":"C · Our clinic","objective_ids":[],"points":0,"image_asset_id":"hr-img-map","image_alt":"Map of My Clinic sites: five in Jeddah, one in Petro-Rabigh, one in Riyadh.","mode":"explore","require_all":true,"prompt_html":"<p>Seven sites. You'll hear these codes every day — open each pin.</p>","regions":[{"id":"j1","shape":"rect","coords":[300,150,90,60],"label_html":"J1 — North Jeddah","feedback_html":"<p>Our first full-service outpatient clinic. Opened 2017.</p>"},{"id":"j2","shape":"rect","coords":[430,190,90,60],"label_html":"J2 — East Jeddah","feedback_html":"<p>Our second full-service outpatient clinic. Opened 2021.</p>"},{"id":"d1","shape":"rect","coords":[350,250,90,60],"label_html":"D1 — Dental Centre","feedback_html":"<p>Our dental centre in Jeddah. Opened 2022.</p>"},{"id":"j3","shape":"rect","coords":[280,300,90,60],"label_html":"J3 — community clinic","feedback_html":"<p>Our first community clinic in Jeddah. Opened 2025. Name pending decision B5 / D3.</p>"},{"id":"j4","shape":"rect","coords":[300,380,90,60],"label_html":"J4 — community clinic","feedback_html":"<p>Our second community clinic in Jeddah. Opened 2026. Name pending decision B5 / D3.</p>"},{"id":"prc","shape":"circle","coords":[250,470,32],"label_html":"PRC — Petro-Rabigh","feedback_html":"<p>Our clinic in Petro-Rabigh. Opened 2023.</p>"},{"id":"r1","shape":"circle","coords":[980,300,32],"label_html":"R1 — Riyadh","feedback_html":"<p>Our first clinic in Riyadh — a flagship. Opened 2024.</p>"}],"feedback":{"correct_html":"<p>You have explored all seven My Clinic branches across Jeddah, Rabigh and Riyadh.</p>","incorrect_html":"<p>Select each branch pin on the map to explore all seven sites.</p>","show_correct_answer":true},"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"flashcards","title":"Meet our leaders","prompt_html":"<p>Flip each card to see what each leader owns. Names and photos are in the live staff directory.</p>","cards":[{"front_html":"<strong>Chief Executive Officer</strong>","back_html":"<p>Sets the direction and answers to the board.</p>"},{"front_html":"<strong>Chief Medical Officer</strong>","back_html":"<p>Owns clinical standards and outcomes.</p>"},{"front_html":"<strong>Chief Operating Officer</strong>","back_html":"<p>Runs the clinics day to day.</p>"},{"front_html":"<strong>Chief Finance Officer</strong>","back_html":"<p>Looks after the money that makes it possible.</p>"}],"id":"hr-022","section":"C · Our clinic","points":0,"objective_ids":[],"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"flashcards","id":"hr-023","title":"What we've been recognised for","section":"C · Our clinic","objective_ids":[],"points":0,"prompt_html":"<p>Flip each card. Accreditation is measured, not given — and it has to be earned again.</p>","cards":[{"front_html":"CBAHI accreditation","back_html":"Accredited by CBAHI, the Central Board for Accreditation of Healthcare Institutions. MCJ1 scored 98.67 in 2022 and MCJ2 scored 100 in 2023. <em>Pending B7.</em>","front_asset_id":"hr-img-award-star","front_alt":"Decorative icon."},{"front_html":"Best Clinical Patient Outcome","back_html":"Best Clinical Patient Outcome, 2019–2020. <em>Pending B7.</em>","front_asset_id":"hr-img-award-trophy","front_alt":"Decorative icon."},{"front_html":"Best new clinic for customer service","back_html":"Best new clinic for customer service, 2018. <em>Pending B7.</em>","front_asset_id":"hr-img-award-star","front_alt":"Decorative icon."},{"front_html":"Best New Premium Clinic","back_html":"Best New Premium Clinic, 2018–19. <em>Pending B7.</em>","front_asset_id":"hr-img-award-trophy","front_alt":"Decorative icon."},{"front_html":"Most innovative corporate wellness initiative","back_html":"Most innovative corporate wellness initiative in Saudi Arabia, 2019. <em>Pending B7.</em>","front_asset_id":"hr-img-award-star","front_alt":"Decorative icon."}],"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"content_slide","id":"hr-030","title":"Our code of ethics","section":"D · Ethics & patients' rights","objective_ids":[],"points":0,"layout":"text","body_html":"<p><strong>Respect</strong> — uphold the rights, privacy and dignity of patients, families and colleagues.</p><p><strong>Integrity</strong> — transparent practice; disclose any potential conflict of interest.</p><p><strong>Accountability</strong> — a culture that encourages reporting safety concerns and adherence to policy.</p><p><strong>Innovation &amp; collaboration</strong> — support research and community engagement to improve quality and outcomes.</p><p><strong>Ethical dilemma? Incident report within 24 hours + ethics team.</strong> <em>Pending B14 / D8.</em></p>","media_asset_id":"hr-img-ethics-icons","media_alt":"Four icons for Respect, Integrity, Accountability, and Innovation and collaboration."},{"type":"exploration","id":"hr-030p","title":"Your principle","prompt_html":"<p>Which ethics principle will you use most in your role?</p>","input_kind":"choice","store_key":"hr_ethic","choices":[{"id":"respect","text_html":"Respect"},{"id":"integrity","text_html":"Integrity"},{"id":"accountability","text_html":"Accountability"},{"id":"innovation","text_html":"Innovation &amp; collaboration"}],"section":"D · Ethics & patients' rights","points":0,"objective_ids":[],"on_enter":[{"var":"xp","op":"add","value":2}]},{"section":"D · Ethics & patients' rights","points":0,"objective_ids":[],"type":"branching","id":"hr-031-ask","title":"A supplier you know","prompt_html":"<p><strong>Next: a decision.</strong> Want a hint from Noor first? It's a nudge, not the answer.</p>","choices":[{"id":"ask","text_html":"<strong>Ask Noor</strong>","goto_screen_id":"hr-031-hint","set_vars":[{"var":"hint","op":"set","value":1}]},{"id":"go","text_html":"<strong>I'm ready</strong>","goto_screen_id":"hr-031","set_vars":[{"var":"hint","op":"set","value":0}]}],"default_goto":"hr-031"},{"section":"D · Ethics & patients' rights","points":0,"objective_ids":[],"type":"content_slide","id":"hr-031-hint","title":"Noor's hint","layout":"text_media","body_html":"<p><strong>Noor:</strong> “Ask yourself: would I be comfortable if everyone could see this decision? When in doubt, declare it and ask.”</p>","media_asset_id":"char-noor-explaining","media_alt":"Noor, the course guide.","visible_if":{"var":"hint","cmp":"==","value":1}},{"type":"decision_scenario","id":"hr-031","title":"A supplier you know","section":"D · Ethics & patients' rights","objective_ids":["hr-o2"],"points":15,"pass_score":3,"start_node_id":"n1","intro_html":"<div class=\"mc-host noor\">{{asset:char-noor-avatar-neutral}}<span>Noor · Safety liaison</span></div><p>Three moments, three decisions. Nobody is watching.</p>","nodes":[{"id":"n1","prompt_html":"<p>You're on a panel evaluating three suppliers for a clinic fit-out. One bidder is your cousin's company. The evaluation starts in an hour.</p>","image_asset_id":"hr-img-ethics-meeting","image_alt":"A small meeting room where a supplier evaluation is being discussed.","choices":[{"id":"n1a","text_html":"Say nothing — you can score their bid fairly.","score_delta":0,"goto_node_id":"n2","feedback_html":"<p><strong>⚠ Risk for you and the team.</strong></p><p>Even a fair score looks compromised. Integrity means disclosing a potential conflict of interest before the work starts, in procurement as much as in recruitment.</p>"},{"id":"n1b","text_html":"Declare the conflict in writing to the panel chair and step back from scoring that bid.","score_delta":1,"goto_node_id":"n2","feedback_html":"<p><strong>✓ Better for you and the team.</strong></p><p>Right. You disclose the potential conflict and remove yourself from the decision. Nobody has to guess afterwards, including you.</p>"},{"id":"n1c","text_html":"Step out of the meeting quietly and say nothing.","score_delta":0,"goto_node_id":"n2","feedback_html":"<p><strong>⚠ Risk for you and the team.</strong></p><p>Leaving is better than scoring, but silence doesn't help: the panel still doesn't know why, and the conflict stays undocumented. Declare it, then step back.</p>"}]},{"id":"n2","prompt_html":"<p>A colleague from another department asks you to “help” a patient skip the queue, and offers you a gift.</p>","image_asset_id":"hr-img-ethics-corridor","image_alt":"A clinic corridor with a reception desk and two patients waiting.","choices":[{"id":"n2a","text_html":"Decline, and explain that access to care is not something we trade.","score_delta":1,"goto_node_id":"n3","feedback_html":"<p><strong>✓ Better for you and the team.</strong></p><p>Right. Fair access is part of Respect — every patient in that queue is waiting for the same reason. A gift makes it a transaction.</p>"},{"id":"n2b","text_html":"Do it once, then return the gift.","score_delta":0,"goto_node_id":"n3","feedback_html":"<p><strong>⚠ Risk for you and the team.</strong></p><p>Returning the gift afterwards doesn't undo it. Someone else waited longer because of a favour, and the gift makes it a transaction.</p>"},{"id":"n2c","text_html":"Ask the patient to wait outside and slot them in when it's quiet.","score_delta":0,"goto_node_id":"n3","feedback_html":"<p><strong>⚠ Risk for you and the team.</strong></p><p>Quiet or not, that patient is still moving ahead of people who waited. Decline, and say why.</p>"}]},{"id":"n3","prompt_html":"<p>A week later you're not sure whether something you saw counts as an ethical issue. Nobody else has raised it.</p>","image_asset_id":"hr-img-ethics-desk","image_alt":"A desk with a laptop open on an incident report form.","choices":[{"id":"n3a","text_html":"Wait until you're certain before involving anyone.","score_delta":0,"goto_node_id":null,"feedback_html":"<p><strong>⚠ Risk for you and the team.</strong></p><p>Waiting is the common mistake. The policy doesn't ask you to be certain; it asks you to act on the dilemma you have.</p>"},{"id":"n3b","text_html":"Raise it with a colleague or the committee, and complete an incident report within 24 hours so the ethics team can advise.","score_delta":1,"goto_node_id":null,"feedback_html":"<p><strong>✓ Better for you and the team.</strong></p><p>Right. Consult colleagues for anything beyond your expertise, and complete an incident report within twenty-four hours so the ethics team can guide you. That's Accountability working.</p>"},{"id":"n3c","text_html":"Mention it informally to your line manager and leave it there.","score_delta":0,"goto_node_id":null,"feedback_html":"<p><strong>⚠ Risk for you and the team.</strong></p><p>A quiet word is a start, but it leaves no record and no route to advice. Report it within twenty-four hours and bring the ethics team in.</p>"}]}],"feedback":{"correct_html":"<p>Three out of three. You declared the conflict, you held the line on queue-jumping, and you used the reporting route instead of guessing. That is Integrity and Accountability as behaviour, not as a poster.</p>","incorrect_html":"<p>Below three. The pattern to hold on to: disclose a conflict early, never trade access for a favour, and when you genuinely don't know, report it within twenty-four hours and ask the ethics team.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10},{"var":"meter","op":"add","value":1}],"on_wrong":[{"var":"meter","op":"add","value":-1}],"on_enter":[{"var":"hint","op":"set","value":0}]},{"type":"drag_drop","id":"hr-032","title":"Rights or responsibilities?","section":"D · Ethics & patients' rights","objective_ids":["hr-o2"],"points":10,"prompt_html":"<p>Nine statements from the notice in reception. Sort them into the right column.</p>","targets":[{"id":"right","label_html":"Patient right"},{"id":"resp","label_html":"Patient responsibility"}],"items":[{"id":"it1","text_html":"Access to care regardless of race, gender or disability","correct_target_id":"right"},{"id":"it2","text_html":"Information and informed consent before treatment","correct_target_id":"right"},{"id":"it3","text_html":"Privacy and confidentiality","correct_target_id":"right"},{"id":"it4","text_html":"Pain management","correct_target_id":"right"},{"id":"it5","text_html":"Refuse treatment after understanding the risks","correct_target_id":"right"},{"id":"it6","text_html":"Ask for a patient advocacy representative","correct_target_id":"right"},{"id":"it7","text_html":"Give accurate health information","correct_target_id":"resp"},{"id":"it8","text_html":"Follow the treatment plan and attend appointments","correct_target_id":"resp"},{"id":"it9","text_html":"Respect other patients and staff","correct_target_id":"resp"}],"feedback":{"correct_html":"<p>Right. Six rights and three responsibilities. The full notice is posted in the reception area if you ever need to point someone to it.</p>","incorrect_html":"<p>Not quite. A right is what the patient can expect from us. A responsibility is what we ask of them so that we can look after them safely. Look again at the three that ask the patient to <em>do</em> something.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"mcq","id":"hr-033","title":"She said no","section":"D · Ethics & patients' rights","objective_ids":["hr-o2"],"points":5,"prompt_html":"<p>A patient refuses a blood test after the doctor has explained the risks. What is the right response?</p>","options":[{"id":"a","text_html":"Respect the refusal, check she understood the risks, document it, and tell the doctor","correct":true,"feedback_html":"<p>Right. Refusal of treatment is a patient right once the risks are understood. Your job is to check understanding, document the refusal, and inform the doctor.</p>"},{"id":"b","text_html":"Ask the clinic manager to persuade her to agree","feedback_html":"<p>Bringing in a manager to talk her round turns a right into pressure. She can refuse once she understands the risks.</p>"},{"id":"c","text_html":"Take the sample anyway, because the doctor ordered it","feedback_html":"<p>Proceeding against a competent patient's refusal is not consent. Stop and escalate to the doctor instead.</p>"},{"id":"d","text_html":"Ask a family member to consent instead","feedback_html":"<p>A family member cannot replace her consent. Only she can decide, once she understands the risks.</p>"}],"multi_select":false,"feedback":{"correct_html":"<p>Right. Refusal of treatment is a patient right once the risks are understood. Your job is to check understanding, document the refusal, and inform the doctor.</p>","incorrect_html":"<p>Not that one. A competent patient can refuse after the risks have been explained. Persuasion, proceeding anyway, or substituting a family member's consent all override a right.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"content_slide","id":"hr-040","title":"Where help lives","section":"E · Your leave","objective_ids":[],"points":0,"layout":"text","body_html":"<p><strong>Your HR help desk</strong> — one per business unit. <em>Role mailbox addresses pending B6 / D5.</em></p><p><strong>Request everything in Oracle.</strong> If it's a request, it needs a record.</p><p><strong>Full rules:</strong> HR Quick Reference (PDF, 2 pages) <em>⚠ Draft — pending: job aid not produced yet</em></p>","media_asset_id":"hr-img-help-icons","media_alt":"Three icons: HR help desk, Oracle self-service, and the HR Quick Reference PDF."},{"type":"accordion","id":"hr-041","title":"Leave at a glance","section":"E · Your leave","objective_ids":[],"points":0,"prompt_html":"<p>Nine types. Open the one you need — the full tables are in the Quick Reference.</p>","items":[{"title":"Annual","body_html":"<p>After probation, with your line manager's approval. Carry over up to 5 days; use them by end of March (consulting-room physicians: end of June). <em>Pending B9.</em></p>"},{"title":"Sick","body_html":"<p>Tell your line manager. Valid medical report required. First 30 days full pay; days 31–90 <em>pending B1</em>; days 91–120 unpaid.</p>"},{"title":"Work injury","body_html":"<p>Covers work hours and commuting. <strong>Report to your line manager and HR the same day or the next day.</strong></p>"},{"title":"Maternity","body_html":"<p>12 weeks. You may start up to 4 weeks before the expected delivery date.</p>"},{"title":"Exam","body_html":"<p>Paid, for <strong>academic</strong> exams only. Actual exam days only. Documents at least 2 weeks in advance. IELTS, TOEFL and similar are not eligible.</p>"},{"title":"Scientific","body_html":"<p>Paid days per profession each year, for academic exams. Needs the MD's pre-approval. <strong>Cannot be carried over.</strong> <em>Pending B10.</em></p>"},{"title":"Hajj","body_html":"<p>Muslim employees with two full years of service. 10–15 days including Eid. Hajj permit copy required. <em>Pending B11.</em></p>"},{"title":"Compassionate","body_html":"<p>Marriage 5 days · paternity 3 · immediate relative 5 · sibling 3 · death of a husband <em>pending B2</em>.</p>"},{"title":"Official holidays","body_html":"<p>Eid al-Fitr 4 days · Eid al-Adha 4 days · Founding Day 22 February · National Day 23 September.</p>"}],"on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"matching","id":"hr-042","title":"How many days?","section":"E · Your leave","objective_ids":["hr-o3"],"points":5,"prompt_html":"<p>Four grades, four entitlements. Match each grade to its annual leave, in working days. <em>Entitlement pending B9.</em></p>","pairs":[{"id":"p1","left_html":"Grade H","right_html":"30 working days"},{"id":"p2","left_html":"Grade G","right_html":"27 working days"},{"id":"p3","left_html":"Grade F and Consultant","right_html":"25 working days"},{"id":"p4","left_html":"Grades A to E","right_html":"22 working days"}],"feedback":{"correct_html":"<p>Right. Entitlement rises with grade: 30, 27, 25 and 22 working days. Your contract and the Quick Reference both show your own grade.</p>","incorrect_html":"<p>Not quite. The entitlement rises with grade, from 22 working days at grades A to E up to 30 at grade H. Match them again.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"worked_example","id":"hr-043","title":"Forty days of sick leave","section":"E · Your leave","objective_ids":[],"points":0,"fading":"partial","intro_html":"<p>A colleague is off sick for 40 days in one year, with valid medical reports from My Clinic. How is the pay worked out?</p>","steps":[{"action_html":"<p><strong>Days 1–30</strong> — tell your line manager you are unwell.</p>","rationale_html":"<p>Notification is the first requirement. Sick leave is accepted only with a valid medical report, and your manager needs to know today, not at the end of it.</p>"},{"action_html":"<p><strong>Days 1–30</strong> — full salary.</p>","rationale_html":"<p>The first thirty days of valid sick leave in a year are paid in full.</p>"},{"action_html":"<p><strong>Days 31–40</strong> — reduced pay. <em>Per the slide as written: 25% deducted, so 75% of salary. Pending B1.</em></p>","rationale_html":"<p>The second band cuts pay by a quarter. Continuous and separated periods count the same way, so the band follows the total days in the year, not one absence.</p>"},{"action_html":"<p><strong>Days 91–120</strong> — unpaid.</p>","rationale_html":"<p>The bands run 1–30, 31–90 and 91–120. Forty days never reaches this band, but it's the ceiling you should know.</p>"},{"action_html":"<p>Check the report: from outside My Clinic, it needs <strong>Staff Health Clinic approval</strong>.</p>","rationale_html":"<p>Reports from My Clinic are accepted as they are. Anything from another provider has to be approved, or the leave isn't valid.</p>"}],"self_explanation_prompt_html":"<p>What changes if the medical report comes from another hospital?</p>","on_enter":[{"var":"xp","op":"add","value":2}]},{"section":"E · Your leave","points":0,"objective_ids":[],"type":"branching","id":"hr-044-ask","title":"The leave desk","prompt_html":"<p><strong>Next: a decision.</strong> Want a hint from Noor first? It's a nudge, not the answer.</p>","choices":[{"id":"ask","text_html":"<strong>Ask Noor</strong>","goto_screen_id":"hr-044-hint","set_vars":[{"var":"hint","op":"set","value":1}]},{"id":"go","text_html":"<strong>I'm ready</strong>","goto_screen_id":"hr-044","set_vars":[{"var":"hint","op":"set","value":0}]}],"default_goto":"hr-044"},{"section":"E · Your leave","points":0,"objective_ids":[],"type":"content_slide","id":"hr-044-hint","title":"Noor's hint","layout":"text_media","body_html":"<p><strong>Noor:</strong> “Check each request against the rule for that leave type: who qualifies, how long they have served, and what documents they need.”</p>","media_asset_id":"char-noor-explaining","media_alt":"Noor, the course guide.","visible_if":{"var":"hint","cmp":"==","value":1}},{"type":"decision_scenario","id":"hr-044","title":"The leave desk","section":"E · Your leave","objective_ids":["hr-o3"],"points":15,"pass_score":3,"start_node_id":"n1","intro_html":"<div class=\"mc-host noor\">{{asset:char-noor-avatar-neutral}}<span>Noor · Safety liaison</span></div><p>Four colleagues, four questions. You're the one they've asked.</p>","nodes":[{"id":"n1","prompt_html":"<p><strong>Yousuf</strong> is a lab technician. He asks for two days of scientific leave, and he already has the MD's pre-approval for his documents. How many days can he take this year?</p>","image_asset_id":"hr-img-leavedesk","image_alt":"An HR service desk with a laptop and two chairs.","choices":[{"id":"n1a","text_html":"Two days — that's the technician allowance, and unused days can't be carried over.","score_delta":1,"goto_node_id":"n2","feedback_html":"<p><strong>✓ Better for you and the team.</strong></p><p>Right. Scientific leave is 2 days a year for lab and radiology technicians, 3 for nurses, 4 for pharmacists, 5 for other physicians and dentists, and 7 for consultants. It also can't be carried over.</p>"},{"id":"n1b","text_html":"Seven days — that's the allowance.","score_delta":0,"goto_node_id":"n2","feedback_html":"<p><strong>⚠ Risk for you and the team.</strong></p><p>Seven days is the consultants' allowance. Technicians get two. The allowance follows the profession, not the request.</p>"},{"id":"n1c","text_html":"None — scientific leave is only for consultants and physicians.","score_delta":0,"goto_node_id":"n2","feedback_html":"<p><strong>⚠ Risk for you and the team.</strong></p><p>Not so. Every profession in the table has an allowance; technicians have the smallest, at two days a year.</p>"},{"id":"n1d","text_html":"Two days now, and he can carry the rest into next year.","score_delta":0,"goto_node_id":"n2","feedback_html":"<p><strong>⚠ Risk for you and the team.</strong></p><p>The days are right, the carry-over isn't. Scientific leave cannot be carried over — unused days are lost.</p>"}]},{"id":"n2","prompt_html":"<p><strong>Amal</strong> is a nurse. She asks for exam leave to sit IELTS next month, and she has her documents ready.</p>","image_asset_id":"hr-img-leavedesk","image_alt":"An HR service desk with a laptop and two chairs.","choices":[{"id":"n2a","text_html":"Refuse: IELTS is not an academic examination, and it's named as not eligible.","score_delta":1,"goto_node_id":"n3","feedback_html":"<p><strong>✓ Better for you and the team.</strong></p><p>Right. Exam leave is paid leave for academic examinations only, and IELTS, TOEFL and Microsoft certifications are named as not eligible. Having the documents ready doesn't change eligibility.</p>"},{"id":"n2b","text_html":"Approve it — she has her documents in on time.","score_delta":0,"goto_node_id":"n3","feedback_html":"<p><strong>⚠ Risk for you and the team.</strong></p><p>Documents matter, but eligibility comes first. IELTS is not an academic examination and is named as not eligible.</p>"},{"id":"n2c","text_html":"Approve half the exam days as a goodwill gesture.","score_delta":0,"goto_node_id":"n3","feedback_html":"<p><strong>⚠ Risk for you and the team.</strong></p><p>Well meant, but the rule is about the type of exam, not the number of days. IELTS is not eligible, so there are no days to approve.</p>"}]},{"id":"n3","prompt_html":"<p><strong>Reem</strong> is a pharmacist with one full year of service. She asks for Hajj leave and has her Hajj permit ready.</p>","image_asset_id":"hr-img-leavedesk","image_alt":"An HR service desk with a laptop and two chairs.","choices":[{"id":"n3a","text_html":"Not yet — Hajj leave needs two full years of continuous service.","score_delta":1,"goto_node_id":"n4","feedback_html":"<p><strong>✓ Better for you and the team.</strong></p><p>Right. Two full years of continuous service is the eligibility rule, and one year doesn't meet it. The permit is needed, but it doesn't shorten the service requirement.</p>"},{"id":"n3b","text_html":"Yes — one year of service is enough.","score_delta":0,"goto_node_id":"n4","feedback_html":"<p><strong>⚠ Risk for you and the team.</strong></p><p>It isn't. Hajj leave is for Muslim employees with two full years of continuous service.</p>"},{"id":"n3c","text_html":"Yes, now that she has the Hajj permit.","score_delta":0,"goto_node_id":"n4","feedback_html":"<p><strong>⚠ Risk for you and the team.</strong></p><p>The permit is a requirement, not a substitute. Without two full years of service she isn't eligible, permit or not.</p>"}]},{"id":"n4","prompt_html":"<p><strong>Sara</strong> is a receptionist. She slipped on the way into work this morning and her ankle is painful. What does she need to do?</p>","image_asset_id":"hr-img-leavedesk","image_alt":"An HR service desk with a laptop and two chairs.","choices":[{"id":"n4a","text_html":"Tell her line manager and HR today or tomorrow — commuting is covered as a work injury.","score_delta":1,"goto_node_id":null,"feedback_html":"<p><strong>✓ Better for you and the team.</strong></p><p>Right. Work injury covers commuting as well as work hours, and the deadline is the same day or the following day. HR then reports the case to GOSI.</p>"},{"id":"n4b","text_html":"Wait and see whether she needs time off before reporting it.","score_delta":0,"goto_node_id":null,"feedback_html":"<p><strong>⚠ Risk for you and the team.</strong></p><p>Waiting is the mistake this rule exists to prevent. The report has to go to her line manager and HR the same day or the next day, whether or not she ends up taking time off.</p>"},{"id":"n4c","text_html":"Tell her commuting accidents aren't covered.","score_delta":0,"goto_node_id":null,"feedback_html":"<p><strong>⚠ Risk for you and the team.</strong></p><p>They are. Work injury applies during work hours and while commuting to and from work, for Saudi and expatriate employees alike.</p>"}]}],"feedback":{"correct_html":"<p>Three or four. You checked eligibility before you answered, which is the whole job at this desk: type of leave, who qualifies, and what document is missing.</p>","incorrect_html":"<p>Fewer than three. The habit to build is to check three things every time — the type of leave, the eligibility rule, and the document. Two of these four turned on eligibility, not on paperwork.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10},{"var":"meter","op":"add","value":1}],"on_wrong":[{"var":"meter","op":"add","value":-1}],"on_enter":[{"var":"hint","op":"set","value":0}]},{"type":"adaptive_practice","id":"hr-045","title":"Leave rules: quick practice","section":"E · Your leave","objective_ids":["hr-o3"],"points":15,"max_items":6,"target_success":0.7,"pass_ratio":0.6,"adaptive":{"strategy":"elo"},"prompt_html":"<p>Answer until the practice says you're ready. It stops early if you've got it.</p>","items":[{"id":"q1","difficulty":0.2,"prompt_html":"<p>How many unused annual leave days can you carry over?</p>","options":[{"id":"a","text_html":"Up to 5","correct":true},{"id":"b","text_html":"Up to 10"},{"id":"c","text_html":"All of them"}],"explain_html":"<p>Carry-over is capped at 5 days. Anything above that is lost at the end of the carry-over window.</p>","scaffold_html":"<p>The cap is a small number — single digits.</p>"},{"id":"q2","difficulty":0.35,"prompt_html":"<p>Carried-over annual leave must be used by when?</p>","options":[{"id":"a","text_html":"End of March","correct":true},{"id":"b","text_html":"End of June"},{"id":"c","text_html":"End of the year"}],"explain_html":"<p>Carried-over leave has to be used by the end of March of the following year.</p>","scaffold_html":"<p>It's the end of a spring month.</p>"},{"id":"q3","difficulty":0.65,"prompt_html":"<p>A consulting-room physician carries over leave. By when must it be used?</p>","options":[{"id":"a","text_html":"End of March"},{"id":"b","text_html":"End of June","correct":true},{"id":"c","text_html":"End of the year"}],"explain_html":"<p>Consulting-room physicians have a later deadline: the end of June.</p>","scaffold_html":"<p>This group gets three months more than everyone else.</p>"},{"id":"q4","difficulty":0.3,"prompt_html":"<p>How long is maternity leave?</p>","options":[{"id":"a","text_html":"12 weeks","correct":true},{"id":"b","text_html":"10 weeks"},{"id":"c","text_html":"8 weeks"}],"explain_html":"<p>Maternity leave is 12 weeks.</p>","scaffold_html":"<p>It's measured in weeks, not months — and it's the longest of the three options.</p>"},{"id":"q5","difficulty":0.6,"prompt_html":"<p>How early can maternity leave start?</p>","options":[{"id":"a","text_html":"Up to 2 weeks before the due date"},{"id":"b","text_html":"Up to 4 weeks before the due date","correct":true},{"id":"c","text_html":"On the due date only"}],"explain_html":"<p>You may start up to 4 weeks before the expected delivery date.</p>","scaffold_html":"<p>The allowance is measured in weeks before the due date.</p>"},{"id":"q6","difficulty":0.5,"prompt_html":"<p>Exam leave documents must be submitted how far in advance?</p>","options":[{"id":"a","text_html":"At least 2 weeks","correct":true},{"id":"b","text_html":"At least 1 week"},{"id":"c","text_html":"On the day of the exam"}],"explain_html":"<p>Documents — the exam schedule and course schedule, plus a result transcript afterwards — must go in at least two weeks in advance.</p>","scaffold_html":"<p>Think in weeks, and it's more than one.</p>"},{"id":"q7","difficulty":0.25,"prompt_html":"<p>How many days of leave for your own marriage?</p>","options":[{"id":"a","text_html":"5 calendar days","correct":true},{"id":"b","text_html":"3 days"},{"id":"c","text_html":"10 days"}],"explain_html":"<p>Marriage leave is 5 calendar days.</p>","scaffold_html":"<p>Marriage attracts the same number of days as bereavement of an immediate relative.</p>"},{"id":"q8","difficulty":0.3,"prompt_html":"<p>How many days of paternity leave?</p>","options":[{"id":"a","text_html":"3 days","correct":true},{"id":"b","text_html":"5 days"},{"id":"c","text_html":"7 days"}],"explain_html":"<p>Paternity leave is 3 days.</p>","scaffold_html":"<p>It's the same number as bereavement of a sibling.</p>"},{"id":"q9","difficulty":0.45,"prompt_html":"<p>Bereavement leave for the death of a sibling?</p>","options":[{"id":"a","text_html":"3 calendar days","correct":true},{"id":"b","text_html":"5 calendar days"},{"id":"c","text_html":"10 calendar days"}],"explain_html":"<p>Death of a sibling is 3 calendar days. Death of an immediate relative — spouse, parent or child — is 5.</p>","scaffold_html":"<p>Immediate relatives attract more days than siblings.</p>"},{"id":"q10","difficulty":0.2,"prompt_html":"<p>How many days is each Eid holiday?</p>","options":[{"id":"a","text_html":"4 days each","correct":true},{"id":"b","text_html":"3 days each"},{"id":"c","text_html":"5 days each"}],"explain_html":"<p>Eid al-Fitr and Eid al-Adha are each 4 days.</p>","scaffold_html":"<p>Both Eids are the same length.</p>"},{"id":"q11","difficulty":0.2,"prompt_html":"<p>When is Founding Day?</p>","options":[{"id":"a","text_html":"22 February","correct":true},{"id":"b","text_html":"23 September"},{"id":"c","text_html":"1 January"}],"explain_html":"<p>Founding Day is 22 February. National Day is 23 September — the two are easy to swap.</p>","scaffold_html":"<p>It's a February date, and the other national holiday falls in September.</p>"},{"id":"q12","difficulty":0.75,"prompt_html":"<p>Can unused scientific leave be carried over?</p>","options":[{"id":"a","text_html":"No, never","correct":true},{"id":"b","text_html":"Yes, up to 5 days"},{"id":"c","text_html":"Yes, with the MD's approval"}],"explain_html":"<p>Scientific leave cannot be carried over. It also needs the MD's pre-approval, but approval doesn't create a carry-over.</p>","scaffold_html":"<p>Approval and carry-over are two different rules; only one of them is mentioned in the source.</p>"}],"feedback":{"correct_html":"<p>You've got the leave numbers. Carry-over, maternity, compassionate and the holidays are the four people ask about most — they're all in the Quick Reference.</p>","incorrect_html":"<p>Leave numbers are worth a second look in the HR Quick Reference. The ones people mix up are the carry-over deadline, Founding Day versus National Day, and sibling versus immediate-relative bereavement.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"content_slide","id":"hr-050","title":"What GOSI is","section":"F · Pay & social insurance","objective_ids":[],"points":0,"layout":"text","body_html":"<p><strong>GOSI</strong> — General Organization for Social Insurance.</p><p>Saudi employees only, until retirement at 60.</p><p>9.75% you + 11.75% My Clinic = <strong>21.5%</strong> of basic + housing. <em>Rates pending B12.</em></p>","media_asset_id":"hr-img-gosi-bar","media_alt":"GOSI contribution: the employee pays 9.75%, My Clinic pays 11.75%, a total of 21.5%."},{"type":"worked_example","id":"hr-051","title":"Working out 585 riyals","section":"F · Pay & social insurance","objective_ids":[],"points":0,"fading":"partial","intro_html":"<p>Basic 4,800 + housing 1,200. What is the monthly GOSI deduction from your salary? <em>Rates pending B12.</em></p>","steps":[{"action_html":"<p>Add basic and housing: 4,800 + 1,200 = <strong>6,000</strong>.</p>","rationale_html":"<p>GOSI is charged on basic salary <strong>plus housing allowance</strong>, not on basic alone and not on total pay with allowances and bonuses.</p>"},{"action_html":"<p>Apply the employee rate: 6,000 × <strong>9.75%</strong>.</p>","rationale_html":"<p>Only your share is deducted from your salary. The company's 11.75% is paid on top and never appears as a deduction on your payslip.</p>"},{"action_html":"<p>Result: <strong>585 SAR</strong> deducted each month.</p>","rationale_html":"<p>6,000 × 0.0975 = 585. This is the line you'll see on your payslip.</p>","artifact_asset_id":"hr-img-gosi-bar","artifact_caption":"Your 9.75% employee share (585 SAR) sits alongside My Clinic's 11.75% contribution."}],"self_explanation_prompt_html":"<p>Which part of the salary is the percentage applied to?</p>","on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"fill_blank","id":"hr-052","title":"Your turn","section":"F · Pay & social insurance","objective_ids":["hr-o4"],"points":10,"case_sensitive":false,"prompt_html":"<p>Basic 6,000 + housing 1,500. Your monthly GOSI deduction = ___ SAR. <em>Rates pending B12.</em></p>","blanks":[{"id":"b1","accepted":["731.25","731.25 SAR","731.25 SR","731.25 riyals","731.25 Saudi riyals","731","731 SAR"]}],"feedback":{"correct_html":"<p>Right. Basic 6,000 + housing 1,500 = 7,500, and 7,500 × 9.75% = <strong>731.25 SAR</strong> a month.</p>","incorrect_html":"<p>Not quite. Add basic and housing first — that's 7,500 — then take 9.75% of that, not of the basic alone.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"worked_example","id":"hr-053","title":"Working out overtime","section":"F · Pay & social insurance","objective_ids":[],"points":0,"fading":"partial","intro_html":"<p>Basic 6,000. What is your overtime rate on a normal working day, and on a public holiday? <em>Eligibility by grade pending B3.</em></p>","steps":[{"action_html":"<p>Hourly rate: 6,000 ÷ (30 × 8) = 6,000 ÷ 240 = <strong>25 SAR/hour</strong>.</p>","rationale_html":"<p>The formula uses a 30-day month at 8 hours a day, so 240 hours. Everything else in the calculation hangs off this one number.</p>","artifact_asset_id":"hr-img-gosi-bar","artifact_caption":"Hourly rate = basic salary ÷ 30 days ÷ 8 hours, then multiplied by 1.5 (regular) or 2.0 (public holiday)."},{"action_html":"<p>Normal working day: 25 × 1.5 = <strong>37.50 SAR/hour</strong>.</p>","rationale_html":"<p>Overtime on a normal working day is paid at time and a half.</p>"},{"action_html":"<p>Public holiday: 25 × 2 = <strong>50 SAR/hour</strong>.</p>","rationale_html":"<p>Overtime on a public holiday is paid at double time. Note it's the same hourly rate — only the multiplier changes.</p>"}],"self_explanation_prompt_html":"<p>Why is the hourly rate worked out from 240 hours, not 208?</p>","on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"mcq","id":"hr-054","title":"Four hours on Tuesday","section":"F · Pay & social insurance","objective_ids":["hr-o4"],"points":10,"prompt_html":"<p>Basic 6,000. You work 4 overtime hours on a normal working day. What is the overtime pay?</p>","options":[{"id":"a","text_html":"150 SAR","correct":true,"feedback_html":"<p>Right. Hourly rate is 6,000 ÷ 240 = 25, then 25 × 1.5 × 4 hours = 150 SAR.</p>"},{"id":"b","text_html":"100 SAR","feedback_html":"<p>That's 25 × 4. You've worked out the plain hourly pay and left out the time-and-a-half multiplier.</p>"},{"id":"c","text_html":"200 SAR","feedback_html":"<p>That's 25 × 2 × 4. Double time is for a public holiday, not a normal working day.</p>"},{"id":"d","text_html":"240 SAR","feedback_html":"<p>That doesn't come from the formula. Go back to the hourly rate first: 6,000 ÷ 240.</p>"}],"multi_select":false,"feedback":{"correct_html":"<p>Right. Hourly rate is 6,000 ÷ 240 = 25, then 25 × 1.5 × 4 hours = 150 SAR.</p>","incorrect_html":"<p>Not quite. Build it in three moves: 6,000 ÷ 240 = 25 an hour, × 1.5 for a normal day, × 4 hours.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"matching","id":"hr-060","title":"Which system?","section":"G · Systems & licences","objective_ids":["hr-o5"],"points":10,"prompt_html":"<p>Six tasks, four systems. Match each task to where it happens.</p>","pairs":[{"id":"p1","left_html":"Request annual leave","right_html":"Oracle"},{"id":"p2","left_html":"Ask for an employment certificate","right_html":"Oracle"},{"id":"p3","left_html":"Accept your employment contract","right_html":"Qiwa"},{"id":"p4","left_html":"Renew your professional licence","right_html":"Mumaris (SCFHS)"},{"id":"p5","left_html":"Read the employee guide and corporate discounts","right_html":"Intranet"},{"id":"p6","left_html":"Resign","right_html":"Oracle"}],"feedback":{"correct_html":"<p>Right. Three of the six run through Oracle, because they're all requests that need a record. Contracts are accepted on Qiwa, licences are renewed on Mumaris, and the guide lives on the intranet.</p>","incorrect_html":"<p>Not all six. Ask yourself which of these are <em>requests</em> — those go through Oracle. The contract and the licence are external platforms, and the guide is just reading.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"simulation","id":"hr-061","title":"Book your leave in Oracle","section":"G · Systems & licences","objective_ids":["hr-o5"],"points":15,"prompt_html":"<p>Five steps. These screenshots come from a test account, so nothing here is real.</p>","steps":[{"image_asset_id":"hr-img-oracle-1","image_alt":"Oracle sign-in page with empty username and password fields and a Sign In button.","instruction_html":"<p>Sign in to Oracle.</p>","regions":[{"id":"signin","shape":"rect","coords":[1180,620,180,56],"correct":true,"label_html":"Sign In"}],"hint_html":"<p>Use the <em>Sign In</em> button under the password field.</p>"},{"image_asset_id":"hr-img-oracle-2","image_alt":"Oracle home page with a Time and Absences tile in the quick actions area.","instruction_html":"<p>Open the area where you manage your time and leave.</p>","regions":[{"id":"timeabs","shape":"rect","coords":[260,300,320,200],"correct":true,"label_html":"Time and Absences"}],"hint_html":"<p>Look for <em>Time and Absences</em> in the quick actions.</p>"},{"image_asset_id":"hr-img-oracle-3","image_alt":"Oracle Time and Absences page with an Add Leaves tile.","instruction_html":"<p>Open the page where you add a new leave request.</p>","regions":[{"id":"addleaves","shape":"rect","coords":[420,310,220,140],"correct":true,"label_html":"Add Leaves"}],"hint_html":"<p>Look for <em>Add Leaves</em> under Time and Absences.</p>"},{"image_asset_id":"hr-img-oracle-4","image_alt":"Oracle Add Leaves form with the leave-type drop-down open.","instruction_html":"<p>Choose <em>Annual</em> from the leave-type list.</p>","regions":[{"id":"leavetype","shape":"rect","coords":[300,260,420,60],"correct":true,"label_html":"Leave type"}],"hint_html":"<p>The leave type is a drop-down near the top of the form.</p>"},{"image_asset_id":"hr-img-oracle-5","image_alt":"Oracle Add Leaves form with dates entered and a Submit button.","instruction_html":"<p>Send the request.</p>","regions":[{"id":"submit","shape":"rect","coords":[1500,900,180,56],"correct":true,"label_html":"Submit"}],"hint_html":"<p><em>Submit</em> sits at the bottom of the form.</p>"}],"feedback":{"correct_html":"<p>That's the whole flow: sign in, Time and Absences, Add Leaves, choose the leave type and dates, submit. Your manager approves it in the same system, so you can see where it's got to.</p><p class=\"companion-tip companion-omar\"><strong>Omar's tip:</strong> Submitted isn't approved. Check the request status in Oracle before you book flights or hotels.</p>","incorrect_html":"<p>Not every step. The route is always the same: sign in, then Time and Absences, then Add Leaves. The last two steps are the form itself.</p><p class=\"companion-tip companion-omar\"><strong>Omar's tip:</strong> Submitted isn't approved. Check the request status in Oracle before you book flights or hotels.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10},{"var":"meter","op":"add","value":1}],"on_wrong":[{"var":"meter","op":"add","value":-1}]},{"type":"true_false","id":"hr-062","title":"Thirty days left","section":"G · Systems & licences","objective_ids":["hr-o5"],"points":5,"prompt_html":"<p>If your professional licence will expire in less than 30 days without renewal, HR may suspend you from work. <em>Pending B13.</em></p>","correct":true,"feedback":{"correct_html":"<p>True. With fewer than 30 days to expiry and no renewal, HR may suspend you. Renew early on Mumaris: My Clinic covers the expense claim, but it does not pay penalties for late renewal.</p>","incorrect_html":"<p>It's true. My Clinic may suspend you if your licence has under 30 days left and hasn't been renewed. Renew on Mumaris well before that — the company pays the fee claim, not the late penalties.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"content_slide","id":"hr-070","title":"Your ID card and benefits","section":"H · ID, benefits & dress code","objective_ids":[],"points":0,"layout":"text","blocks":[{"html":"<p><strong>Lost card</strong> — email HR. Replacement fee <em>pending B4</em>.</p><p><strong>Damaged card</strong> — replaced free of charge.</p>"},{"asset_id":"hr-img-idcard","caption":"A My Clinic staff ID badge on a lanyard."},{"html":"<p><strong>Benefits from day one:</strong> health insurance · annual performance bonuses · employee development · hybrid work policy · internal advancement · discounts.</p>"},{"asset_id":"hr-img-benefits-wheel","caption":"Benefits wheel: health insurance, annual performance bonuses, employee development, hybrid work, internal advancement and discounts."}]},{"type":"drag_drop","id":"hr-071","title":"What do you wear?","section":"H · ID, benefits & dress code","objective_ids":["hr-o6"],"points":10,"prompt_html":"<p>Six rules, three groups. Place each rule where it applies.</p>","targets":[{"id":"front","label_html":"Front office"},{"id":"medical","label_html":"Medical team"},{"id":"back","label_html":"Back office"}],"items":[{"id":"it1","text_html":"Uniform for every shift","correct_target_id":"front"},{"id":"it2","text_html":"Scrubs and coat","correct_target_id":"medical"},{"id":"it3","text_html":"Business attire","correct_target_id":"back"},{"id":"it4","text_html":"Minimal jewellery","correct_target_id":"medical"},{"id":"it5","text_html":"Professional shoes","correct_target_id":"medical"},{"id":"it6","text_html":"No casual days","correct_target_id":"back"}],"feedback":{"correct_html":"<p>Right. Front office wears the clinic uniform. The medical team wears scrubs and a coat with professional shoes and minimal jewellery. Back office is business attire, with no casual days.</p>","incorrect_html":"<p>Not all six. Three of them belong to the medical team, two to back office and one to front office. The one people mix up is “no casual days” — that's the back-office wording; front office says “no casual attire”.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"accordion","id":"hr-072-clinical","title":"Your dress code","prompt_html":"<p><strong>For your role.</strong> What the dress code means for your team.</p>","items":[{"title":"Every shift","body_html":"<p>Scrubs and a coat, professional shoes, minimal jewellery. <em>Proposed — SME to confirm.</em></p>"}],"visible_if":{"var":"role","cmp":"==","value":"clinical"},"points":0,"objective_ids":[],"section":"H · ID, benefits & dress code","on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"accordion","id":"hr-072-front","title":"Your dress code","prompt_html":"<p><strong>For your role.</strong> What the dress code means for your team.</p>","items":[{"title":"Every shift","body_html":"<p>The clinic uniform on every shift; no casual attire. <em>Proposed — SME to confirm.</em></p>"}],"visible_if":{"var":"role","cmp":"==","value":"front"},"points":0,"objective_ids":[],"section":"H · ID, benefits & dress code","on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"accordion","id":"hr-072-support","title":"Your dress code","prompt_html":"<p><strong>For your role.</strong> What the dress code means for your team.</p>","items":[{"title":"Every day","body_html":"<p>Business attire; no casual days. <em>Proposed — SME to confirm.</em></p>"}],"visible_if":{"var":"role","cmp":"==","value":"support"},"points":0,"objective_ids":[],"section":"H · ID, benefits & dress code","on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"tabs","id":"hr-072-all","title":"Your dress code","prompt_html":"<p>What the dress code means for your team. Pick a role to compare.</p>","tabs":[{"label":"Medical team","body_html":"<h4>Every shift</h4><p>Scrubs and a coat, professional shoes, minimal jewellery. <em>Proposed — SME to confirm.</em></p>"},{"label":"Front office","body_html":"<h4>Every shift</h4><p>The clinic uniform on every shift; no casual attire. <em>Proposed — SME to confirm.</em></p>"},{"label":"Back office","body_html":"<h4>Every day</h4><p>Business attire; no casual days. <em>Proposed — SME to confirm.</em></p>"}],"visible_if":{"var":"role","cmp":"==","value":"all"},"points":0,"objective_ids":[],"section":"H · ID, benefits & dress code","on_enter":[{"var":"xp","op":"add","value":2}]},{"type":"content_slide","id":"hr-080","title":"If you ever leave","section":"I · Contracts & leaving","objective_ids":[],"points":0,"layout":"text","body_html":"<p><strong>Accept your contract</strong> on Qiwa.</p><p><strong>Resign</strong> in Oracle.</p><p><strong>Notice: 2 months</strong>, honoured by both parties.</p><p><strong>EOS + experience certificate</strong> within 15 days of your last working day.</p>","media_asset_id":"hr-img-exit-icons","media_alt":"Four steps: Qiwa contract, Oracle resignation, two months notice, and end-of-service settlement within 15 days."},{"type":"mcq","id":"hr-081","title":"Three weeks' notice","section":"I · Contracts & leaving","objective_ids":["hr-o6"],"points":5,"prompt_html":"<p>You accept a new job starting in 3 weeks. What happens with your notice?</p>","options":[{"id":"a","text_html":"You must serve the contractual 2 months unless My Clinic agrees otherwise; submit the resignation in Oracle","correct":true,"feedback_html":"<p>Right. The notice period is two months and it binds both sides, unless My Clinic agrees to something different. And a resignation is a request, so it goes in through Oracle.</p>"},{"id":"b","text_html":"You can leave in 3 weeks — a new job overrides the notice period","feedback_html":"<p>A new job doesn't override the contract. The two months stands unless My Clinic agrees to shorten it.</p>"},{"id":"c","text_html":"Email your manager; Oracle is only for leave requests","feedback_html":"<p>Oracle isn't only for leave. Resignation, letters and certificates are all service requests, and they need a record.</p>"},{"id":"d","text_html":"Give one month: notice is shorter for grades A to E","feedback_html":"<p>The notice period in your contract isn't set by grade in this policy. Assume two months unless your contract says otherwise.</p>"}],"multi_select":false,"feedback":{"correct_html":"<p>Right. The notice period is two months and it binds both sides, unless My Clinic agrees to something different. And a resignation is a request, so it goes in through Oracle.</p>","incorrect_html":"<p>Not that one. The contractual notice is two months, and it binds both sides. You can always ask HR whether they'll agree to less, but you can't assume it.</p>","show_correct_answer":true},"on_correct":[{"var":"xp","op":"add","value":10}]},{"type":"results_breakdown","id":"hr-090","title":"How you did","section":"Z · Close","objective_ids":[],"points":0,"body_html":"<p>One row per objective. Anything below 70% comes with a suggestion.</p>","weak_threshold":70,"show_total":true,"sections":[{"title":"Values & strategy","screen_ids":["hr-011","hr-013"],"advice_html":"<p>Revisit the four values and the 7C pillars. The one to remember: Care is where My Care and patient loyalty sit.</p><p><strong>Open Mission 1 · Our values & strategy</strong> from the menu (☰) to revisit it.</p>"},{"title":"Ethics & patients' rights","screen_ids":["hr-031","hr-032","hr-033"],"advice_html":"<p>Disclose conflicts early, never trade access to care, and when you're unsure, report within 24 hours. A right is what the patient can expect; a responsibility is what we ask of them.</p><p><strong>Open Mission 3 · Ethics & patients' rights</strong> from the menu (☰) to revisit it.</p>"},{"title":"Leave","screen_ids":["hr-042","hr-044","hr-045"],"advice_html":"<p>Check three things on every request: the type of leave, the eligibility rule, and the document. The tables are in the HR Quick Reference.</p><p><strong>Open Mission 4 · Your leave</strong> from the menu (☰) to revisit it.</p>"},{"title":"Pay & social insurance","screen_ids":["hr-052","hr-054"],"advice_html":"<p>GOSI is basic plus housing × 9.75%. Overtime is basic ÷ 240, then × 1.5, or × 2 on a public holiday.</p><p><strong>Open Mission 5 · Pay & social insurance</strong> from the menu (☰) to revisit it.</p>"},{"title":"Systems & licences","screen_ids":["hr-060","hr-061","hr-062"],"advice_html":"<p>Requests go through Oracle. Contracts on Qiwa, licences on Mumaris, guides on the intranet. Renew your licence well before it expires.</p><p><strong>Open Mission 4 · Your leave</strong> from the menu (☰) to revisit it.</p>"},{"title":"ID, dress code & contracts","screen_ids":["hr-071","hr-081"],"advice_html":"<p>Front office wears the uniform, the medical team wears scrubs and a coat, back office is business attire. Notice is two months both ways.</p><p><strong>Open Mission 7 · ID, benefits & dress code and Mission 8 · Contracts & leaving</strong> from the menu (☰) to revisit it.</p>"}]},{"type":"summary","id":"hr-091","title":"You're ready","section":"Z · Close","objective_ids":[],"points":0,"show_score":true,"show_completion":true,"body_html":"<p><strong>You can now:</strong> live the values · raise a concern the right way · answer leave and pay questions · use Oracle, Qiwa and Mumaris · keep your licence valid.</p><p><strong>Keep this:</strong> HR Quick Reference (PDF, 2 pages) <em>⚠ Draft — pending: job aid not produced yet</em></p><p><strong>Please do:</strong> <a href=\"{{survey_url}}\" target=\"_blank\" rel=\"noopener\">the onboarding survey (2 minutes)</a></p><p><strong>Next:</strong> module 07 — Clinical Governance: Quality, Patient Safety &amp; Risk.</p><p>You chose <strong><span data-exploration-ref=\"hr_ethic\"></span></strong> as your principle.</p><p class=\"mc-role-line\"><strong>As a {{role_label}}:</strong> your manager will walk you through your team's first-week checklist.</p><p class=\"mc-xp-final\"><strong>You finished with {{xp}} XP.</strong> Your rank is at the top of the screen.</p>"}]};
